/**
 * Presets
 * Two kinds of starting point:
 *
 *  - JOURNEYS: full spatial sessions for the field view. Sources with clip
 *    timings, keyframe paths and named sections along the timeline.
 *  - MODES: single-screen focus sessions (frequency tools only, no map).
 *
 * Keyframe paths are generated by small helpers instead of being typed out,
 * so a journey stays readable and easy to retune.
 */

const DEFAULT_FADE_IN = 8;
const DEFAULT_FADE_OUT = 15;

/**
 * An arc of keyframes around the listener.
 * @param {Object} o
 *   from/to    start and end angle in degrees (0 = right, 90 = front)
 *   radius     metres, or [start, end] to spiral
 *   z          metres, or [start, end] to rise or fall
 *   volume     the body level, or [start, peak, end] for a slow swell
 *   start/end  seconds
 *   steps      number of keyframes along the path
 *   fadeIn/fadeOut  seconds; the clip opens and closes silently
 */
export function arc(o) {
  const steps = o.steps || 6;
  const kfs = [];
  const pair = (v, t) => (Array.isArray(v) ? v[0] + (v[v.length - 1] - v[0]) * t : v);
  for (let i = 0; i < steps; i++) {
    const t = steps === 1 ? 0 : i / (steps - 1);
    const deg = o.from + (o.to - o.from) * t;
    const rad = (deg * Math.PI) / 180;
    const r = pair(o.radius, t);
    let vol;
    if (Array.isArray(o.volume) && o.volume.length === 3) {
      const [a, peak, b] = o.volume;
      vol = t < 0.5 ? a + (peak - a) * (t / 0.5) : peak + (b - peak) * ((t - 0.5) / 0.5);
    } else {
      vol = pair(o.volume, t);
    }
    kfs.push({
      time: round(o.start + (o.end - o.start) * t, 1),
      x: round(Math.cos(rad) * r, 2),
      y: round(Math.sin(rad) * r, 2),
      z: round(pair(o.z ?? 0, t), 2),
      volume: round(vol, 3),
      easing: o.easing || 'ease-in-out',
    });
  }
  return applyFades(kfs, o);
}

/** A source that holds one position and only changes level over time. */
export function hold(o) {
  const at = o.at || [0, 0, 0];
  const levels = Array.isArray(o.volume) ? o.volume : [o.volume];
  const steps = levels.length;
  const kfs = levels.map((v, i) => ({
    time: round(o.start + (o.end - o.start) * (steps === 1 ? 0 : i / (steps - 1)), 1),
    x: at[0], y: at[1], z: at[2],
    volume: round(v, 3),
    easing: 'ease-in-out',
  }));
  if (steps === 1) kfs.push({ ...kfs[0], time: o.end });
  return applyFades(kfs, o);
}

/**
 * Wrap a keyframe list in a silent open and close. The path is sampled at the
 * fade points, so the sound arrives and leaves where it would have been rather
 * than jumping to the first keyframe's position.
 */
export function applyFades(kfs, o = {}) {
  if (kfs.length < 2) return kfs;
  const start = kfs[0].time;
  const end = kfs[kfs.length - 1].time;
  const span = end - start;
  if (span <= 0) return kfs;

  let fadeIn = o.fadeIn !== undefined ? o.fadeIn : DEFAULT_FADE_IN;
  let fadeOut = o.fadeOut !== undefined ? o.fadeOut : DEFAULT_FADE_OUT;
  if (fadeIn <= 0 && fadeOut <= 0) return kfs;

  // Never let the fades eat the whole clip.
  const budget = span * 0.8;
  if (fadeIn + fadeOut > budget) {
    const k = budget / (fadeIn + fadeOut);
    fadeIn = round(fadeIn * k, 1);
    fadeOut = round(fadeOut * k, 1);
  }

  const inAt = round(start + fadeIn, 1);
  const outAt = round(end - fadeOut, 1);
  const out = [];

  if (fadeIn > 0) {
    out.push({ ...sample(kfs, start), time: start, volume: 0 });
    out.push(sample(kfs, inAt));
  } else {
    out.push({ ...kfs[0] });
  }

  for (const kf of kfs) {
    if (kf.time > inAt && kf.time < outAt) out.push({ ...kf });
  }

  if (fadeOut > 0) {
    out.push(sample(kfs, outAt));
    out.push({ ...sample(kfs, end), time: end, volume: 0 });
  } else {
    out.push({ ...kfs[kfs.length - 1] });
  }

  return out.filter((kf, i, a) => i === 0 || kf.time > a[i - 1].time);
}

/** Linear sample of a keyframe list at a time. */
function sample(kfs, time) {
  if (time <= kfs[0].time) return { ...kfs[0], time };
  const last = kfs[kfs.length - 1];
  if (time >= last.time) return { ...last, time };
  let prev = kfs[0];
  let next = last;
  for (let i = 0; i < kfs.length - 1; i++) {
    if (time >= kfs[i].time && time <= kfs[i + 1].time) { prev = kfs[i]; next = kfs[i + 1]; break; }
  }
  const span = next.time - prev.time;
  const k = span > 0 ? (time - prev.time) / span : 0;
  const lerp = (a, b) => round(a + (b - a) * k, 3);
  return {
    time: round(time, 1),
    x: lerp(prev.x, next.x),
    y: lerp(prev.y, next.y),
    z: lerp(prev.z, next.z),
    volume: lerp(prev.volume, next.volume),
    easing: prev.easing || 'ease-in-out',
  };
}

function round(v, digits) {
  const f = Math.pow(10, digits || 0);
  return Math.round(v * f) / f;
}

const src = (id, type, name, kfs, extra = {}) => ({
  id, type, name,
  x: kfs[0].x, y: kfs[0].y, z: kfs[0].z,
  volume: Math.max(...kfs.map(k => k.volume)),
  startTime: kfs[0].time,
  duration: round(kfs[kfs.length - 1].time - kfs[0].time, 1),
  keyframes: kfs,
  ...extra,
});

